// server.mjs — خادم عروض الأسعار (وحدات Node المدمجة فقط: http وfs)
// يستمع على المنفذ 3000، يقدم index.html على المسار /، ويعالج POST /api/quote
// بتحقق صارم بدون أي تحويل أنواع (لا نصوص ولا null ولا أرقام عشرية).

import http from 'node:http';
import fs from 'node:fs';

const PORT = 3000;
const HOST = '0.0.0.0';

// حدود العمل المطلوبة
const MAX_ITEMS = 100;
const MAX_UNIT_PRICE_CENTS = 10000000;   // 0 .. 10,000,000
const MAX_QUANTITY = 10000;              // 1 .. 10,000
const MAX_DISCOUNT_PERCENT = 100;        // 0 .. 100
const MAX_SHIPPING_CENTS = 1000000;      // 0 .. 1,000,000
const MAX_SUBTOTAL_CENTS = 1000000000;   // سقف مجموع الأسعار قبل الخصم
const MAX_BODY_BYTES = 1000000;          // سقف حجم جسم الطلب

// ---------- أدوات مساعدة ----------

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
  });
  res.end(body);
}

function invalid(res) {
  sendJson(res, 400, { error: 'invalid' });
}

// كائن عادي فقط (ليس null ولا مصفوفة)
function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// عدد صحيح آمن ضمن مجال — يرفض النصوص وnull والأرقام العشرية وNaN وInfinity
function isIntInRange(value, min, max) {
  return Number.isSafeInteger(value) && value >= min && value <= max;
}

// ---------- التحقق والحساب ----------

// يعيد كائن النتيجة عند النجاح أو null عند أي مخالفة
function validateAndCompute(payload) {
  if (!isPlainObject(payload)) return null;

  const { items, discountPercent, shippingCents } = payload;

  // items: مصفوفة من 1 إلى 100 عنصرًا
  if (!Array.isArray(items) || items.length < 1 || items.length > MAX_ITEMS) return null;

  // discountPercent وshippingCents: أعداد صحيحة آمنة ضمن المجالات (بلا تحويل أنواع)
  if (!isIntInRange(discountPercent, 0, MAX_DISCOUNT_PERCENT)) return null;
  if (!isIntInRange(shippingCents, 0, MAX_SHIPPING_CENTS)) return null;

  const seenSkus = new Set();
  let subtotalCents = 0;

  for (const item of items) {
    if (!isPlainObject(item)) return null;

    const { sku, unitPriceCents, quantity } = item;

    // sku: نص غير فارغ بعد trim (رفض أي نوع آخر)
    if (typeof sku !== 'string') return null;
    const trimmedSku = sku.trim();
    if (trimmedSku.length === 0) return null;

    // sku غير مكرر (بعد trim)
    if (seenSkus.has(trimmedSku)) return null;
    seenSkus.add(trimmedSku);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isIntInRange(unitPriceCents, 0, MAX_UNIT_PRICE_CENTS)) return null;

    // quantity: عدد صحيح من 1 إلى 10000
    if (!isIntInRange(quantity, 1, MAX_QUANTITY)) return null;

    subtotalCents += unitPriceCents * quantity;
  }

  // سقف مجموع الأسعار قبل الخصم
  if (subtotalCents > MAX_SUBTOTAL_CENTS) return null;

  // تقريب النصف للأعلى بدون أخطاء عائمة: floor((subtotal*percent + 50) / 100)
  const discountCents = Math.floor((subtotalCents * discountPercent + 50) / 100);

  // رسوم الشحن لا تدخل في حساب الخصم
  const totalCents = subtotalCents - discountCents + shippingCents;

  // الحقول الأربعة فقط
  return { subtotalCents, discountCents, shippingCents, totalCents };
}

// ---------- معالج POST /api/quote ----------

function handleQuote(req, res) {
  const chunks = [];
  let size = 0;
  let rejected = false;

  req.on('data', (chunk) => {
    if (rejected) return;
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      rejected = true;
      chunks.length = 0;
      invalid(res);
      req.destroy();
      return;
    }
    chunks.push(chunk);
  });

  req.on('error', () => {
    if (!rejected && !res.writableEnded) {
      rejected = true;
      invalid(res);
    }
  });

  req.on('end', () => {
    if (rejected || res.writableEnded) return;

    let payload;
    try {
      payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch {
      // JSON معطوب
      invalid(res);
      return;
    }

    const result = validateAndCompute(payload);
    if (result === null) {
      invalid(res);
      return;
    }
    sendJson(res, 200, result);
  });
}

// ---------- خادم HTTP ----------

const server = http.createServer((req, res) => {
  let pathname;
  try {
    pathname = new URL(req.url, `http://${req.headers.host || 'localhost'}`).pathname;
  } catch {
    invalid(res);
    return;
  }

  // واجهة API
  if (pathname === '/api/quote') {
    if (req.method !== 'POST') {
      res.setHeader('Allow', 'POST');
      sendJson(res, 405, { error: 'invalid' });
      return;
    }
    handleQuote(req, res);
    return;
  }

  // الصفحة الرئيسية
  if ((req.method === 'GET' || req.method === 'HEAD') && (pathname === '/' || pathname === '/index.html')) {
    fs.readFile(new URL('./index.html', import.meta.url), (err, data) => {
      if (err) {
        sendJson(res, 500, { error: 'internal' });
        return;
      }
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Length': data.length,
        'Cache-Control': 'no-store',
      });
      res.end(req.method === 'HEAD' ? undefined : data);
    });
    return;
  }

  sendJson(res, 404, { error: 'invalid' });
});

server.listen(PORT, HOST, () => {
  console.log(`Quote server listening on http://localhost:${PORT}`);
});

